test('lineDiscount with bulk discount (10+ units)', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const result = lineDiscount(line);
  const baseDiscount = 0;
  const amountAfterBase = 10000 - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  assert.equal(result, bulkDiscount);
});

test('lineDiscount without bulk discount (under 10 units)', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount exactly 10 units triggers bulk', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  const result = lineDiscount(line);
  assert.ok(result > 0);
});

test('lineDiscount exactly 9 units no bulk', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount combines base and bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const total = 10000;
  const baseDiscount = 1000;
  const amountAfterBase = total - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const expected = baseDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expected);
});

test('lineDiscount bulk applied to amount after base discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 50 };
  const total = 1000;
  const baseDiscount = 500;
  const amountAfterBase = total - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const expected = baseDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expected);
});

test('lineVat calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const total = 10000;
  const totalDiscount = lineDiscount(line);
  const base = total - totalDiscount;
  const expected = Math.round(base * 0.21);
  assert.equal(lineVat(line), expected);
});

test('invoiceTotals with bulk discount single line', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const result = invoiceTotals(invoice);

  const subtotal = 10000;
  const baseDiscount = 0;
  const amountAfterBase = subtotal - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const totalDiscount = baseDiscount + bulkDiscount;
  const vat = Math.round((subtotal - totalDiscount) * 0.21);
  const total = subtotal - totalDiscount + vat;

  assert.equal(result.subtotal, subtotal);
  assert.equal(result.discount, totalDiscount);
  assert.equal(result.vat, vat);
  assert.equal(result.total, total);
});

test('invoiceTotals with bulk discount mixed with non-bulk', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const result = invoiceTotals(invoice);

  const subtotal = 15000;
  const bulkLine = 10000;
  const nonBulkLine = 5000;
  const bulkDiscount = Math.round(bulkLine * 0.025);
  const totalDiscount = bulkDiscount;
  const vat = Math.round((bulkLine - bulkDiscount) * 0.21) + Math.round(nonBulkLine * 0.21);

  assert.equal(result.subtotal, subtotal);
  assert.equal(result.discount, totalDiscount);
  assert.equal(result.vat, vat);
});

test('lineDiscount with large quantity bulk discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  const result = lineDiscount(line);
  const expected = Math.round(100000 * 0.025);
  assert.equal(result, expected);
});

test('invoiceTotals with bulk discount and line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const result = invoiceTotals(invoice);

  const subtotal = 10000;
  const baseDiscount = 1000;
  const amountAfterBase = subtotal - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const totalDiscount = baseDiscount + bulkDiscount;
  const vat = Math.round((subtotal - totalDiscount) * 0.21);

