test('vatSummary with discount on taxable line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  const lineTotal = 85000;
  const tierDiscount = 4250;
  const lineDiscount = 8500;
  const baseDiscount = tierDiscount + lineDiscount;
  const amountAfterBase = lineTotal - baseDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const base = lineTotal - baseDiscount - bulkDiscount;
  assert.equal(result[0].base, base);

